#!/usr/bin/env python3
"""sites.json -> src/generated/sites.generated.h (run by build.ps1)."""

from __future__ import annotations

import sys
from pathlib import Path

from sitetable import Site, load

KIND_CPP = {
    "jmp": "RsxrKind::Jmp",
    "jmp_atomic8": "RsxrKind::JmpAtomic8",
    "rel32": "RsxrKind::Rel32",
    "call": "RsxrKind::Call",
    "ref": "RsxrKind::Ref",
    "callref": "RsxrKind::CallRef",
    "bytes": "RsxrKind::Bytes",
}


def render(checksum: int, sites: list[Site]) -> str:
    lines = [
        "// Generated by tools/gen_sites.py from sites.json - do not edit.",
        "#pragma once",
        '#include "platform/sites.h"',
        "",
        f"static const unsigned kRsxrPeChecksum = 0x{checksum:08X}u;",
        "static const RsxrSite kRsxrSites[] = {",
    ]

    def row(s: Site) -> str:
        rel_at, rel_size, insn_end = s.target if s.target else (-1, 0, 0)
        expect = s.expect.hex(" ").upper()
        write = s.write.hex(" ").upper()
        return (
            f'    {{"{s.id}", "{s.pattern}", {s.offset}, "{expect}", {KIND_CPP[s.kind]}, '
            f'{s.length}, {rel_at}, {rel_size}, {insn_end}, "{write}"}},'
        )

    main = [s for s in sites if not s.group]
    psarc = [s for s in sites if s.group == "psarc"]
    lines += [row(s) for s in main]
    lines += [
        "};",
        f"static const int kRsxrSiteCount = {len(main)};",
        "",
        "// The plain-PSARC unit (features/psarc/psarc.h): resolved and written early, on their own.",
        "static const RsxrSite kRsxrPsarcSites[] = {",
    ]
    lines += [row(s) for s in psarc]
    lines += ["};", f"static const int kRsxrPsarcSiteCount = {len(psarc)};", ""]
    fast = [s for s in sites if s.group == "fast"]
    lines += [
        "// [test] fast (features/testdrive/testdrive.h): resolved and written early, on their own.",
        "static const RsxrSite kRsxrFastSites[] = {",
    ]
    lines += [row(s) for s in fast]
    lines += ["};", f"static const int kRsxrFastSiteCount = {len(fast)};", ""]
    return "\n".join(lines)


def main(argv: list[str]) -> int:
    # --without NAME: leave out that feature's own sites (src/features/NAME/sites.json; build.ps1 -Public: the private extras)
    without = tuple(argv[i + 1] for i, a in enumerate(argv) if a == "--without")
    args = [a for i, a in enumerate(argv) if a != "--without" and (i == 0 or argv[i - 1] != "--without")]
    src, dst = Path(args[0]), Path(args[1])
    checksum, sites = load(src, without)
    dst.parent.mkdir(parents=True, exist_ok=True)
    dst.write_text(render(checksum, sites), encoding="utf-8", newline="\n")
    print(f"{dst}: {len(sites)} sites")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
